import React,{useEffect,useState} from 'react';
import {View,Text} from 'react-native';
import {CameraView,useCameraPermissions} from 'expo-camera';
export default function Q(){
  const[p,req]=useCameraPermissions();const[v,setV]=useState('');
  useEffect(()=>{if(!p?.granted)req();},[p]);
  if(!p?.granted)return(<Text>need cam</Text>);
  return(<View style={{flex:1}}><CameraView style={{flex:1}} barcodeScannerSettings={{barcodeTypes:['qr']}} onBarcodeScanned={({data})=>setV(data)}/><Text>{v}</Text></View>);}
